def transform(grid):
    """Extend the colored pattern by reflection across the fixed cross."""
    h, w = len(grid), len(grid[0])
    # The 9-valued cross divides the grid into four regions. Reflect the
    # non-background pixels from the upper-right region into its counterpart.
    cross_r = next(r for r, row in enumerate(grid) if all(v == 9 for v in row))
    cross_c = next(c for c in range(w) if all(grid[r][c] == 9 for r in range(h)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (7, 9):
                # Reflect across the horizontal and vertical axes of the cross.
                for rr, cc in ((2 * cross_r - r, c), (r, 2 * cross_c - c), (2 * cross_r - r, 2 * cross_c - c)):
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 9:
                        out[rr][cc] = grid[r][c]
    return out
